fn sql_paths(value: &Value, paths: &mut BTreeSet<String>) {
    match value {
        Value::String(path)
            if Path::new(path)
                .extension()
                .is_some_and(|extension| extension == "sql") =>
        {
            paths.insert(path.clone());
        }
        Value::Array(values) => {
            for value in values {
                sql_paths(value, paths);
            }
        }
        Value::Object(values) => {
            for value in values.values() {
                sql_paths(value, paths);
            }
        }
        _ => {}
    }
}

